#include <vector>
#include <list>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20};
    int& ref_v = v[0];

    // Vector reallocation invalidates reference
    v.reserve(100); 
    // std::cout << ref_v; // DANGER: UB if reallocation occurred

    std::list<int> l = {30, 40};
    auto it_l = l.begin();

    // List insertion does NOT invalidate existing iterators
    l.push_back(50);
    std::cout << "List element: " << *it_l << std::endl; // Safe: 30

    return 0;
}
